package com.byawasaya.platform.onboarding;
import java.time.Instant; import java.util.List; import java.util.UUID; import jakarta.validation.constraints.*;
public final class OnboardingDtos {
 private OnboardingDtos(){}
 public record RegisterRequest(@NotBlank @Size(max=120) String storeName,@NotBlank @Size(max=120) String ownerName,@NotBlank @Email @Size(max=180) String email,@NotBlank @Size(max=30) String phone,@NotBlank @Pattern(regexp="[a-zA-Z0-9][a-zA-Z0-9-]{2,59}") String slug,@NotBlank @Size(min=12,max=72) String password,@NotBlank @Size(min=3,max=100) String citizenshipNumber,@NotBlank @Pattern(regexp="RETAIL|WHOLESALE|BOTH") String businessType,@NotBlank @Size(min=3,max=100) String panVatNumber,@NotBlank @Size(max=120) String registrationNumber,@NotBlank @Size(max=180) String registrationAuthority,@NotBlank @Size(max=500) String registeredAddress,@NotBlank @Size(max=100) String province,@NotBlank @Size(max=100) String district,@NotBlank @Size(max=120) String municipality,@NotBlank @Pattern(regexp="[A-Z][A-Z0-9_]{2,39}") String selectedPlanCode,@NotBlank @Pattern(regexp="classic") String selectedTemplateKey,@Size(max=60) String promoCode,@Size(max=100) String draftToken){}
 public record DraftLeadRequest(@NotBlank @Size(min=32,max=100) String draftToken,@NotBlank @Size(max=120) String storeName,@NotBlank @Size(max=30) String phone,@NotBlank @Pattern(regexp="[a-zA-Z0-9][a-zA-Z0-9-]{2,59}") String slug,@NotBlank @Pattern(regexp="[A-Z][A-Z0-9_]{2,39}") String selectedPlanCode){}
 public record DraftLeadRestoreRequest(@NotBlank @Size(min=32,max=100) String draftToken){}
 public record DraftLeadResponse(String storeName,String slug,String phone,String selectedPlanCode){}
 public record DraftUpdateRequest(@NotBlank @Size(min=3,max=100) String citizenshipNumber,@NotBlank @Pattern(regexp="RETAIL|WHOLESALE|BOTH") String businessType,@NotBlank @Size(min=3,max=100) String panVatNumber,@NotBlank @Size(max=120) String registrationNumber,@NotBlank @Size(max=180) String registrationAuthority,@NotBlank @Size(max=500) String registeredAddress,@NotBlank @Size(max=100) String province,@NotBlank @Size(max=100) String district,@NotBlank @Size(max=120) String municipality,@NotBlank @Pattern(regexp="[A-Z][A-Z0-9_]{2,39}") String selectedPlanCode,@NotBlank @Pattern(regexp="classic") String selectedTemplateKey,@Size(max=60) String promoCode,@Size(max=2000) String applicantNotes){}
 public record ReviewRequest(@NotBlank @Pattern(regexp="UNDER_REVIEW|NEEDS_CORRECTION|APPROVED|REJECTED") String status,@Size(max=2000) String internalNotes,@Size(max=2000) String applicantNotes){}
 public record DocumentResponse(UUID id,String documentType,String originalFilename,String contentType,long sizeBytes,String verificationStatus,String reviewerNote,Instant uploadedAt) { static DocumentResponse from(StoreDocument d){return new DocumentResponse(d.getId(),d.getDocumentType(),d.getOriginalFilename(),d.getContentType(),d.getSizeBytes(),d.getVerificationStatus(),d.getReviewerNote(),d.getUploadedAt());}}
 public record ApplicationResponse(UUID id,UUID businessId,String storeCode,String storeName,String slug,String ownerName,String ownerEmail,String phone,boolean emailVerified,String citizenshipNumber,String businessType,String panVatNumber,String registrationNumber,String registrationAuthority,String registeredAddress,String province,String district,String municipality,String selectedPlanCode,java.math.BigDecimal selectedPlanPriceNpr,String selectedTemplateKey,String promoCode,String status,String applicantNotes,String reviewerNotes,String publicReviewNotes,String reviewerUsername,Instant submittedAt,Instant reviewedAt,Instant createdAt,List<DocumentResponse> documents){ }
 public record MessageResponse(String message){}
}
